SELECT messages.message_no ,messages.language_id,messages.message_title,messages.user_text,messages.technical_text ,messages.icon ,messages.button ,messages.default_button ,messages.msg_severity_level ,messages.print_indicator ,messages.user_input ,messages.window_flag ,messages.date_created ,messages.date_last_modified ,messages.last_maintained_by ,messages.use_long_message ,messages.copy_indicatorFROM messages WHERE ( messages.message_no = 4236 )UNIONSELECT messages.message_no ,message_foreign.language_id,COALESCE(message_foreign.foreign_title,messages.message_title),COALESCE(message_foreign.foreign_text,messages.user_text),messages.technical_text ,messages.icon ,messages.button ,messages.default_button ,messages.msg_severity_level ,messages.print_indicator ,messages.user_input ,messages.window_flag ,messages.date_created ,messages.date_last_modified ,messages.last_maintained_by ,messages.use_long_message ,messages.copy_indicatorFROM messages INNER JOIN message_foreign ON messages.message_no = message_foreign.message_noWHERE ( messages.message_no = 4236 )